//! The Lua side of Sarthi's API, from its schemas: the modules whose functions call Sarthi's requests (`init.lua` and
//! `api.lua`), and the types of the settings and the window config for lua-language-server (`_meta.lua`)

use std::fmt::Write;

use rpc::sarthi::{Request, Settings, WindowConfig};
use serde_json::Value;

use crate::help::{Function, api_functions};
use crate::schema::{self, Schema};

/// Width of the generated Lua, comments included
const WIDTH: usize = 120;

/// The note at the top of each generated file
const GENERATED: &str = "-- Generated by `cargo xtask docs` from crates/rpc/src/sarthi. Edit that, not this file.\n";

/// `init.lua`: `require('sarthi')`, the functions that aren't the window functions
pub fn init() -> String {
	let api = Schema::of::<Request>();
	let mut out = String::from(GENERATED);
	out.push_str("local rpc = require('sarthi.rpc')\n\nlocal sarthi = {}\n\n");
	out.push_str("-- Neovim's window functions that take a window config, with a `sarthi` table in it\n");
	out.push_str("sarthi.api = require('sarthi.api')\n");
	for function in api_functions(&api).iter().filter(|function| !function.lua.starts_with("api.")) {
		wrapper(&mut out, "sarthi", &function.lua, function);
	}
	out.push_str("\nreturn sarthi\n");
	out
}

/// `api.lua`: `require('sarthi').api`, the window functions
pub fn api() -> String {
	let api = Schema::of::<Request>();
	let mut out = String::from(GENERATED);
	out.push_str("local rpc = require('sarthi.rpc')\n\nlocal api = {}\n");
	for function in api_functions(&api).iter().filter(|function| function.lua.starts_with("api.")) {
		wrapper(&mut out, "api", function.lua.trim_start_matches("api."), function);
	}
	out.push_str("\nreturn api\n");
	out
}

/// `function` as a function of Lua table `table` named `name`, which calls its request
fn wrapper(out: &mut String, table: &str, name: &str, function: &Function) {
	out.push('\n');
	comment(out, "---", &function.doc);
	for param in &function.params {
		let optional = if param.optional { "?" } else { "" };
		comment(out, "---", &format!("@param {}{optional} {} {}", param.name, param.lua_type, param.doc));
	}
	if let Some(returns) = &function.returns {
		let _ = writeln!(out, "---@return {returns}");
	}
	let params: Vec<&str> = function.params.iter().map(|param| param.name.as_str()).collect();
	let args = params.iter().map(|param| format!(", {param}")).collect::<String>();
	let _ = writeln!(out, "function {table}.{name}({})", params.join(", "));
	// In parentheses, not a tail call: the wrapper stays on the stack, so `rpc.request` raises at the caller's line.
	let _ = writeln!(out, "  return (rpc.request('{}'{args}))", function.method);
	out.push_str("end\n");
}

/// `_meta.lua`: the types of the settings and of the window functions' `sarthi` table, as LuaCATS classes and aliases
pub fn meta() -> String {
	let settings = Schema::of::<Settings>();
	let config = Schema::of::<WindowConfig>();
	let mut out = String::from("---@meta\n");
	out.push_str(GENERATED);
	class(&mut out, "Settings", &settings.root);
	class(&mut out, "WindowConfig", &config.root);
	let mut written = vec![String::from("Settings"), String::from("WindowConfig")];
	for (name, def) in settings.defs().chain(config.defs()) {
		if written.contains(name) || matches!(name.as_str(), "Window" | "Buffer") {
			continue;
		}
		written.push(name.clone());
		if def.get("properties").is_some() {
			class(&mut out, name, def);
		} else if name == "Animation" {
			animation(&mut out, def);
		} else {
			out.push('\n');
			comment(&mut out, "---", &schema::doc(def));
			let _ = writeln!(out, "---@alias sarthi.{name} {}", schema::lua_type(def));
		}
	}
	out
}

/// Object `schema` as class `sarthi.name`, every field optional: what's left out has its default
fn class(out: &mut String, name: &str, schema: &Value) {
	out.push('\n');
	comment(out, "---", &schema::doc(schema));
	let _ = writeln!(out, "---@class sarthi.{name}");
	for (key, field) in schema::properties(schema) {
		comment(out, "---", &format!("@field {key}? {} {}", schema::lua_type(field), schema::doc(field)));
	}
}

/// The animations, one class with the keys of every curve
fn animation(out: &mut String, schema: &Value) {
	let curves = schema.get("oneOf").and_then(Value::as_array).cloned().unwrap_or_default();
	let names: Vec<String> = curves
		.iter()
		.filter_map(|curve| curve.pointer("/properties/curve/const").map(schema::lua_value))
		.map(|name| name.replace('"', "'"))
		.collect();
	out.push('\n');
	comment(out, "---", &schema::doc(schema));
	out.push_str("---@class sarthi.Animation\n");
	let _ = writeln!(out, "---@field curve {} Which curve", names.join("|"));
	let mut keys: Vec<&str> = Vec::new();
	for curve in &curves {
		for (key, field) in schema::properties(curve) {
			if key != "curve" && !keys.contains(&key) {
				keys.push(key);
				comment(out, "---", &format!("@field {key}? {} {}", schema::lua_type(field), schema::doc(field)));
			}
		}
	}
}

/// `text` as Lua comment lines starting with `prefix`, wrapped to [`WIDTH`]; Markdown links to help tags are left as
/// their text
fn comment(out: &mut String, prefix: &str, text: &str) {
	let text = plain_links(text);
	// An annotation stays on one line: lua-language-server would take a line after it as something else's doc.
	if text.starts_with('@') {
		let _ = writeln!(out, "{prefix}{}", text.split_whitespace().collect::<Vec<_>>().join(" "));
		return;
	}
	for (index, paragraph) in text.split("\n\n").enumerate() {
		if index > 0 {
			let _ = writeln!(out, "{}", prefix.trim_end());
		}
		let mut line = String::new();
		for word in paragraph.split_whitespace() {
			if !line.is_empty() && prefix.len() + line.len() + 1 + word.len() > WIDTH {
				let _ = writeln!(out, "{prefix}{line}");
				line.clear();
			}
			if !line.is_empty() {
				line.push(' ');
			}
			line.push_str(word);
		}
		if !line.is_empty() {
			let _ = writeln!(out, "{prefix}{line}");
		}
	}
}

/// `text` with its Markdown links to help tags, `[text](#tag)`, as their text
fn plain_links(text: &str) -> String {
	let mut out = String::new();
	let mut rest = text;
	while let Some(start) = rest.find("](#") {
		let Some(open) = rest[..start].rfind('[') else { break };
		let Some(end) = rest[start..].find(')') else { break };
		out.push_str(&rest[..open]);
		out.push_str(&rest[open + 1..start]);
		rest = &rest[start + end + 1..];
	}
	out.push_str(rest);
	out
}
